def _spina_cashctl__parse_amount(value):
    try:
        s = str(value or '').replace(',', '').strip()
        return float(s) if s else 0.0
    except Exception:
        return 0.0

def _spina__norm_dom(_v):
    try:
        if _v in (None, ''):
            return None
        _n = int(str(_v).strip())
        return _n if 1 <= _n <= 31 else None
    except Exception:
        return None

