def _spina__norm_weekday(_v):
    try:
        _s = str(_v or '').strip()
    except Exception:
        _s = ''
    if not _s:
        return ''
    _k = _s[:3].lower()
    _mp = {
        'mon': 'Mon', 'tue': 'Tue', 'wed': 'Wed', 'thu': 'Thu',
        'fri': 'Fri', 'sat': 'Sat', 'sun': 'Sun'
    }
    return _mp.get(_k, '')

def _spina_cashctl__parse_percent(value, default=10.0):
    """Parse a percent input like '10', '10%', or '0.10'. Returns 0..100."""
    try:
        s = str(value or '').replace('%', '').strip()
        if not s:
            return float(default)
        pct = float(s)
        # Helpful shortcut: 0.10 means 10% if user types decimal style.
        if 0 < pct <= 1:
            pct = pct * 100.0
        if pct < 0:
            pct = 0.0
        if pct > 100:
            pct = 100.0
        return pct
    except Exception:
        return float(default)

def join_area_main_sub(main_area: str, sub_area: str = "") -> str:
    """Join main/sub into a single Area string using a consistent separator.

    - If sub_area is blank -> returns main_area
    - Else -> 'Main - Sub'
    """
    try:
        ma = str(main_area or "").strip()
    except Exception:
        ma = ""
    try:
        su = str(sub_area or "").strip()
    except Exception:
        su = ""
    if not ma:
        return su
    if not su:
        return ma
    return f"{ma} - {su}"

def _spina_crc_wrap(c, text, width, font="Helvetica", size=8.0):
    try:
        words = str(text or "").split()
    except Exception:
        words = []
    if not words:
        return [""]
    lines = []
    cur = ""
    for w in words:
        test = (cur + " " + w).strip()
        try:
            ok = c.stringWidth(test, font, size) <= width
        except Exception:
            ok = len(test) * size * 0.5 <= width
        if ok or not cur:
            cur = test
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines or [""]

