def _spina_cashctl__ceil_thousand_units(_amount):
    try:
        b = float(_amount or 0.0)
    except Exception:
        b = 0.0
    if b <= 0:
        return 0
    try:
        return max(1, int((b + 999.999999) // 1000))
    except Exception:
        return 0

