    if not tree:
        return ""
    sel = ()
    try:
        sel = tree.selection()
    except Exception:
        sel = ()
    sel_id = sel[0] if sel else tree.focus()
    if not sel_id:
        return ""
    vals = tree.item(sel_id, "values") or ()
    return self._collectors_name_from_values(vals)

def _collectors_move_area(self, delta):
    try:
        idxs = self.collector_route_areas_lb.curselection()
        if not idxs:
            return
        i = int(idxs[0])
        j = max(0, min(self.collector_route_areas_lb.size() - 1, i + int(delta)))
        if i == j:
            return
        item = self.collector_route_areas_lb.get(i)
        self.collector_route_areas_lb.delete(i)
        self.collector_route_areas_lb.insert(j, item)
        self.collector_route_areas_lb.selection_clear(0, "end")
        self.collector_route_areas_lb.selection_set(j)
    except Exception:
        pass

def _on_collectors_multi_toggle(self):
    """Toggle multi-select mode for Collector Route list (checkbox Sel column)."""
    try:
        multi = bool(self.collector_route_multi_var.get())
    except Exception:
        multi = bool(getattr(self, "_collectors_multi_mode", False))
    try:
        self._collectors_multi_mode = multi
    except Exception:
        pass
    # When turning OFF multi mode, clear checked state
    if not multi:
        try:
            self._collectors_clear_checked()
        except Exception:
            pass
    try:
        self.refresh_collectors()
    except Exception:
        pass

def _collectors_add_area_text(self):
    s = ""
    try:
        s = str(self.collector_route_area_add_var.get() or "").strip()
    except Exception:
        s = ""
    if not s:
        return
    # avoid duplicates (case-insensitive)
    existing = []
    try:
        existing = [str(self.collector_route_areas_lb.get(i) or "").strip().lower() for i in range(self.collector_route_areas_lb.size())]
    except Exception:
        existing = []
    if s.lower() in existing:
        return
    try:
        self.collector_route_areas_lb.insert("end", s)
        self.collector_route_area_add_var.set("")
    except Exception:
        pass

def _on_collectors_tree_wheel(self, event):
    """Ensure mousewheel scroll works on Collector Route list (Treeview)."""
    try:
        tv = getattr(self, "collectors_tree", None)
        if tv is None:
            return
        # Windows / MacOS
        if hasattr(event, "delta") and event.delta:
            # On Windows: event.delta is ±120 multiples.
            tv.yview_scroll(int(-1 * (event.delta / 120)), "units")
            return "break"
        # Linux (Button-4/5)
        if hasattr(event, "num"):
            if event.num == 4:
                tv.yview_scroll(-1, "units")
                return "break"
            if event.num == 5:
                tv.yview_scroll(1, "units")
                return "break"
    except Exception:
        return

def _on_collectors_multi_toggle(self):
    # Leaving multi-select clears checks to avoid accidental bulk actions
    try:
        multi = bool(getattr(self, "collector_route_multi_var", None).get())
