def _spina_cashctl__int_range(value, default, min_value=1, max_value=120):
    try:
        v = int(round(_spina_cashctl__parse_amount(value)))
    except Exception:
        v = int(default)
    if v < min_value:
        v = min_value
    if v > max_value:
        v = max_value
    return v

