def _spina_crc_split_area(_area):
    try:
        if 'split_area_main_sub' in globals():
            return split_area_main_sub(_area)
    except Exception:
        pass
    a = str(_area or "").strip()
    for sep in [" | ", " / ", " - ", " > ", " : ", " — ", " – ", "|", "/", ">", ":"]:
        if sep in a:
            left, right = a.split(sep, 1)
            if left.strip() and right.strip():
                return left.strip(), right.strip()
    return a, ""

def _wrap_to_width(text, font, size, max_w):
    words = (text or "").split()
    lines, cur = [], ""
    for w in words:
        test = (cur + " " + w).strip()
        if not cur or stringWidth(test, font, size) <= max_w:
            cur = test
        else:
            lines.append(cur)
            cur = w
    if cur:
        lines.append(cur)
    return lines

def _spina_crc_clean_reason(_v):
    try:
        s = str(_v or "").strip()
    except Exception:
        s = ""
    if not s:
        return ""
    try:
        s = re.sub(r"\[RC:[^\]]+\]", "", s, flags=re.I).strip()
        s = re.sub(r"\[ADV:[^\]]+\]", "", s, flags=re.I).strip()
        s = re.sub(r"\s+", " ", s).strip()
    except Exception:
        pass
    return s

def _spina_v23_selected_name_lt(self):
    try:
        sel = self.clients_tree.selection()
        if not sel:
            return "", _app__norm_lt_value(self, self._mode_filter())
        iid = sel[0]
        vals = self.clients_tree.item(iid, "values") or ()
        name = str(vals[0] if vals else "").strip()
        lt = _app__norm_lt_value(self, self._mode_filter())
        try:
            tags = self.clients_tree.item(iid, "tags") or ()
            for t in tags:
                if str(t).startswith("lt:"):
                    lt = _app__norm_lt_value(self, str(t).split(":", 1)[1])
                    break
        except Exception:
            pass
        return name, lt
    except Exception:
        return "", _app__norm_lt_value(self, self._mode_filter())

