def _hex_to_rgb01(hex_color: str):
    """'#RRGGBB' -> (r,g,b) floats 0..1"""
    try:
        hx = (hex_color or "").strip()
        if hx.startswith("#") and len(hx) == 7:
            r = int(hx[1:3], 16) / 255.0
            g = int(hx[3:5], 16) / 255.0
            b = int(hx[5:7], 16) / 255.0
            return (r, g, b)
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0590', 'suppressed exception excpass_0590', __spina_exc)
        pass
    return (0.0, 0.0, 0.0)

def _spina__client_due_meta(info: dict | None, as_of=None) -> tuple[str, bool]:
    try:
        flex = _spina__parse_flexible_due_rule(info or {}, target=as_of)
        if flex is not None:
            return flex
    except Exception:
        pass
    try:
        if callable(_spina__client_due_meta_base):
            return _spina__client_due_meta_base(info, as_of=as_of)
    except Exception:
        pass
    return ('', False)

def _candidate_note_keys(name: str) -> list[str]:
    raw = (name or "").strip()
    cands = [raw]
    try:
        san = "".join(ch for ch in raw if ch.isalnum())
        up  = raw.upper()
        up_san = "".join(ch for ch in up if ch.isalnum())
        for v in (san, up, up_san):
            if v and v not in cands:
                cands.append(v)
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0030', 'suppressed exception excpass_0030', __spina_exc)
        pass
    return [c for c in cands if c]

def _spina_v24_cilog_stats(rows):
    rows = list(rows or [])
    clients = set()
    actions = {}
    fields = {}
    today_count = 0
    today = date.today()
    for r in rows:
        name = str(r.get("client") or "").strip()
        if name:
            clients.add(name.lower())
        a = str(r.get("action") or "CHANGE").upper()
        actions[a] = actions.get(a, 0) + 1
        f = str(r.get("field") or "Record")
        fields[f] = fields.get(f, 0) + 1
        if _spina_v24_cilog_parse_day(r.get("when")) == today:
            today_count += 1
    return {
        "total": len(rows),
        "clients": len(clients),
        "today": today_count,
        "actions": actions,
        "fields": fields,
    }

