def _extract_reason_and_color_from_desc(desc: str):
    """Return (reason_text, color_hex) from a transaction description.

    - Removes [ADV:...] tags
    - Extracts and removes [RC:...] token (optional ';D:n' / ';UNTIL:YYYY-MM-DD')
    - Returns trimmed reason text (may be empty)
    """
    if not desc:
        return ("", "")
    color_hex, _meta, s = _parse_reason_color_token_meta(str(desc))
    s = _strip_adv_tags(s)
    s = (s or "").strip()
    return (s, color_hex)

def _spina_auto_close_after_days_value():
    """Return the configured auto-close delay in days. 0 = disabled."""
    try:
        s = load_settings()
    except Exception:
        s = dict(_DEFAULT_SETTINGS)
    try:
        days = int(float(str(s.get('auto_close_after_days', 0) or 0).strip()))
    except Exception:
        days = 0
    if days < 0:
        days = 0
    if days > 365:
        days = 365
    return days

def _parse_reason_color_token(desc: str):
    """Extract a [RC:...] token (hex or a color-name) from the description.

    Returns: (color_hex or "", desc_without_token)
    """
    if not desc:
        return ("", "")
    s = str(desc)
    m = _REASON_COLOR_TOKEN_RE.search(s)
    if not m:
        return ("", s)
    raw = (m.group(1) or "").strip()
    s2 = (s[:m.start()] + s[m.end():]).strip()
    if not raw:
        return ("", s2)
    # Normalize color
    r = raw.strip()
    rl = r.lower()
    if rl in _REASON_COLOR_NAME_MAP:
        return (_REASON_COLOR_NAME_MAP[rl], s2)
    if rl.startswith("#") and len(rl) == 7 and all(ch in "0123456789abcdef" for ch in rl[1:]):
        return (rl, s2)
    # Unknown token content -> ignore color, keep cleaned text
    return ("", s2)

def _parse_ymd(_s: str):
    try:
        return datetime.strptime(str(_s).strip()[:10], "%Y-%m-%d").date()
    except Exception:
        try:
            return date.today()
        except Exception as __spina_exc:
            __spina_logger = globals().get('_log_suppressed_once')
            if callable(__spina_logger):
                __spina_logger('silent_ui_1590__parse_ymd', 'suppressed UI/startup exception at line 1590', __spina_exc)
            return datetime.now().date()

def _parse_any_adv_range(desc: str):
    if not desc:
        return None
    m = _ADV_TAG_RE.search(str(desc))
    if m:
        try:
            return (_dt_advpatch.fromisoformat(m.group(1)).date(),
                    _dt_advpatch.fromisoformat(m.group(2)).date())
        except Exception:
            return None
    m = _ADV_PLAIN_RE.search(str(desc))
    if m:
        try:
            return (_dt_advpatch.fromisoformat(m.group(2)).date(),
                    _dt_advpatch.fromisoformat(m.group(3)).date())
        except Exception:
            return None
    return None

def _resolve_note_key(notes_dict: dict, name: str) -> str:
    """Return an existing key in notes_dict matching 'name' using _candidate_note_keys.
    If none found, default to the original name.
    """
    try:
        for k in _candidate_note_keys(name):
            if k in notes_dict:
                return k
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0031', 'suppressed exception excpass_0031', __spina_exc)
        pass
    return name

