def _log_ignored(context: str, exc: Exception, key: str | None = None):
    """Log an otherwise-ignored exception once per key (to avoid log spam)."""
    try:
        k = (key or context or "ignored")
        if k in _UI_IGNORED_ONCE:
            return
        _UI_IGNORED_ONCE.add(k)
        _log_exc(context, exc)
    except Exception as __spina_exc:
        _log_suppressed_once('excpass_0011', 'suppressed exception excpass_0011', __spina_exc)
        pass

def _spina_refresh_dashboard(self):
    try:
        if not hasattr(self, 'dashboard_tree'):
            return
        self._dashboard_rows = _spina_dashboard_fetch_rows(self)
        _spina_populate_dashboard_tree(self)
        try:
            self.status_var.set('Dashboard refreshed. Completion is based on latest released date.')
        except Exception:
            pass
    except Exception as e:
        try:
            _log_exc('refresh_dashboard', e)
        except Exception:
            pass
        try:
            self.status_var.set('Dashboard refresh failed. See data/spina_app.log.')
        except Exception:
            pass

