def _spina_crc_norm_lt(_v):
    try:
        s = str(_v or "Regular").strip().lower().replace(" ", "").replace("×", "x")
    except Exception:
        s = "regular"
    return "7x7" if ("7x7" in s) else "Regular"

def _spina_dash__norm_lt(value):
    try:
        v = str(value or '').strip().lower().replace('×', 'x').replace(' ', '')
    except Exception:
        v = ''
    return '7x7' if v in ('7x7', '7x7emer', 'emer', 'emergency') or '7x7' in v else 'Regular'

