def _is_write_sql(sql: str) -> bool:
    try:
        if not sql:
            return False
        s = str(sql).lstrip().upper()
        if not s:
            return False
        first = s.split(None, 1)[0]
        return first in {"INSERT","UPDATE","DELETE","REPLACE","CREATE","DROP","ALTER","VACUUM","REINDEX","ANALYZE"}
    except Exception:
        return False

def _safe_string(s: str) -> str:
    """As a last resort, coerce to an encodable string for current font."""
    try:
        # Try WinAnsi encoding check (reportlab default)
        s.encode('latin-1')
        return s
    except Exception:
        try:
            return s.encode('latin-1', 'replace').decode('latin-1')
        except Exception:
            return (s or "")

def _spina__split_payment_mode(value):
    try:
        raw = str(value or '').strip()
    except Exception:
        raw = ''
    if not raw:
        return 'Cash', ''
    key = raw.lower().replace('-', '').replace('_', '').replace(' ', '')
    if key == 'cash':
        return 'Cash', ''
    if key == 'gcash':
        return 'GCASH', ''
    if key == 'atm':
        return 'ATM', ''
    if key in ('other', 'others', 'othermode', 'otherpaymentmode'):
        return 'Others', ''
    return 'Others', raw

