            except Exception:
                pass
    return anchor

def _log_exc(context: str, exc: Exception | None = None):
    """Log exceptions to data/spina_app.log (best-effort)."""
    try:
        if exc is None:
            _logging.exception(context)
        else:
            _logging.error(
                "%s: %s",
                context,
                exc,
                exc_info=(type(exc), exc, exc.__traceback__),
            )
    except Exception:
        try:
            print(f"[SPINA][ERROR] {context}: {exc}", file=sys.stderr)
        except Exception:
            return

def _spina_schedule_auto_daily_close(self):
    """Run auto close now and then check periodically while the app is open."""
    try:
        self.run_auto_daily_close(show_message=False)
    except Exception as e:
        try:
            _log_exc('auto_daily_close.initial', e)
        except Exception:
            pass

    try:
        root = getattr(self, 'root', None)
        if root is None:
            return
        # Check every hour. The date threshold comes from Settings each time.
        root.after(60 * 60 * 1000, lambda: self._schedule_auto_daily_close())
    except Exception:
        pass

