        import re
        name = os.path.basename(str(path or ''))
        m = re.search(r'CollectorRoute[_\s-]+(.+?)[_\s-]+20\d{2}[-_]\d{2}[-_]\d{2}', name, re.I)
        if not m:
            return None
        return m.group(1).replace('_', ' ').strip() or None
    except Exception:
        return None

def _log_suppressed_once(key: str, context: str, exc: Exception | None = None):
    """Log a suppressed exception only once per key (to avoid log spam)."""
    try:
        k = str(key or context or "suppressed")
        if k in _SUPPRESS_LOG_ONCE_KEYS:
            return
        _SUPPRESS_LOG_ONCE_KEYS.add(k)
    except Exception:
        # Never call this function recursively from its own failure path.
        k = str(context or "suppressed")
    try:
        _log_exc(context, exc)
    except Exception:
        try:
            print(f"[SPINA][SUPPRESSED] {context}: {exc}", file=sys.stderr)
        except Exception:
            return

