def run_write(op, retries: int = 8, base_delay: float = 0.08, max_delay: float = 1.20):
    """Retry wrapper for SQLite write operations."""
    import time, random, sqlite3 as _sqlite3
    last = None
    for i in range(max(1, retries)):
        try:
            return op()
        except _sqlite3.OperationalError as e:
            msg = str(e).lower()
            if ("database is locked" in msg) or ("database is busy" in msg):
                last = e
                delay = min(max_delay, base_delay * (2 ** i))
                delay = delay + (random.random() * base_delay)
                time.sleep(delay)
                continue
            raise
    if last:
        raise last
    return op()

